&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot; data-ccp-charstyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;ac0262f4-8a9e-5820-b908-2d943c5f7113|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Calibri&amp;quot;,469777842,&amp;quot;Arial&amp;quot;,469777843,&amp;quot;Calibri&amp;quot;,469777844,&amp;quot;Calibri&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Calibri,Arial&amp;quot;,268442635,&amp;quot;22&amp;quot;,469775450,&amp;quot;normaltextrun&amp;quot;,201340122,&amp;quot;1&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;normaltextrun&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Default Paragraph Font&amp;quot;]}&quot;&gt;AI &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;FactoryOS&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; is Firmus&#39; proprietary operating system for the AI Factory. It governs GPU telemetry, cooling, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;power&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; and grid interaction as one integrated layer, so that every Firmus site can be &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;optimised&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; and &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;monitored&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt; as a single system.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;134245417&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;AI FactoryOS Operations runs that platform in production and owns the 24/7 reliability of AI FactoryOS, Firmus AI Cloud and the platforms built on them, together with the service levels the estate is measured against.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;aaed607e-c2a3-5841-9fb4-41037bfa0faf|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,469769226,&amp;quot;Times New Roman&amp;quot;,201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,201341986,&amp;quot;1&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;paragraph&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;paragraph&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559705,&amp;quot;2057&amp;quot;,335551547,&amp;quot;3081&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,134245417,&amp;quot;true&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;The remit is an engineering one. The function builds the guarded automation, remediation and operational tooling that turn manual response into a software-defined &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;capability, and&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt; builds and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;operates&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt; the shared services the estate&#39;s own operation depends on. The function works closely with the engineering teams that build the platform, supplying the production evidence that shapes what they fix and what they build next.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245417&amp;quot;:true,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Senior Platform Security Engineer&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Role Summary&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
